import{_ as i,o as e,c as t,a2 as a}from"./chunks/framework.CdvW4CUT.js";const b=JSON.parse('{"title":"人物動作/裝備/頭顱","description":"可以調整人物的動作、戴上帽子及取得玩家頭顱等，增加遊玩的趣味性。","frontmatter":{"title":"人物動作/裝備/頭顱","description":"可以調整人物的動作、戴上帽子及取得玩家頭顱等，增加遊玩的趣味性。"},"headers":[],"relativePath":"feature/figure/index.md","filePath":"feature/figure.md"}'),o={name:"feature/figure/index.md"};function r(u,l,c,d,n,h){return e(),t("div",null,[...l[0]||(l[0]=[a('<h1 id="人物動作-裝備-頭顱" tabindex="-1">人物動作/裝備/頭顱 <a class="header-anchor" href="#人物動作-裝備-頭顱" aria-label="Permalink to &quot;人物動作/裝備/頭顱&quot;">​</a></h1><h2 id="坐下、躺下、趴下" tabindex="-1">坐下、躺下、趴下 <a class="header-anchor" href="#坐下、躺下、趴下" aria-label="Permalink to &quot;坐下、躺下、趴下&quot;">​</a></h2><ul><li><p><code>/sit</code><b>坐下</b></p><ul><li>也可以對著<b>樓梯/地毯/半磚</b>按右鍵 <ul><li>如果你不希望按右鍵坐下 請輸入<code>/sittoggle</code><br><img src="https://i.imgur.com/DHg0Whk.png" style="width:15%;"></li></ul></li></ul></li><li><p><code>/lay</code><b>躺下</b><br><img src="https://i.imgur.com/KgHykk7.png" style="width:15%;"></p></li><li><p><code>/crawl</code><b>趴下</b><br><img src="https://i.imgur.com/W7qFQpt.png" style="width:20%;"></p></li></ul><h2 id="戴帽子" tabindex="-1">戴帽子 <a class="header-anchor" href="#戴帽子" aria-label="Permalink to &quot;戴帽子&quot;">​</a></h2><ul><li><code>/hat</code><b>把東西戴在頭上</b><ul><li>手持要戴的東西，輸入指令即可戴上 <ul><li>手上只能有一個物品，超過會無法戴上</li></ul></li><li>若要脫下來，直接打開背包將物品拿下即可</li><li>物品或方塊都可以，呈現的樣式各有不同，請自行體驗 <ul><li>可輸入F5切換視角查看<br><img src="https://i.imgur.com/9F0v3lG.png" style="width:20%;"></li></ul></li></ul></li></ul><h2 id="脫下綁定裝" tabindex="-1">脫下綁定裝 <a class="header-anchor" href="#脫下綁定裝" aria-label="Permalink to &quot;脫下綁定裝&quot;">​</a></h2><ul><li><code>/takeoff &lt;部件名稱&gt;</code><b>脫下綁定的裝備</b><ul><li>如果你不小心穿上有綁定詛咒的裝備，可輸入指令脫下此裝備 <ul><li>主手不能拿東西</li></ul></li><li>脫下頭盔 <code>/takeoff helmet</code></li><li>脫下胸甲 <code>/takeoff chestplate</code></li><li>脫下護腿 <code>/takeoff leggings</code></li><li>脫下靴子 <code>/takeoff boots</code></li></ul></li></ul><h2 id="頭顱獲取" tabindex="-1">頭顱獲取 <a class="header-anchor" href="#頭顱獲取" aria-label="Permalink to &quot;頭顱獲取&quot;">​</a></h2><h3 id="玩家頭顱-獲取條件" tabindex="-1">玩家頭顱 獲取條件 <a class="header-anchor" href="#玩家頭顱-獲取條件" aria-label="Permalink to &quot;玩家頭顱 獲取條件&quot;">​</a></h3><ul><li>使用指定武器來擊殺玩家 <ul><li>手持<font color="red"><b>獄髓斧頭</b></font></li><li>帶有<font color="blue"><b>鋒利五+絲綢附魔</b></font></li><li>被擊殺的玩家的經驗值至少要有<font color="green"><b>3等以上</b></font></li><li>達成上述條件後，該玩家死亡時即會掉落他的頭顱</li></ul></li><li>被擊殺掉落頭顱之玩家，將會扣除1+1的經驗等級 <ul><li>1等為因PVP而死亡的經驗懲罰，未超過十等時則不會扣除</li><li>1等為因掉頭而造成的經驗扣除</li><li>範例 <ul><li>13等被符合條件之武器擊殺而死，此時會掉落頭顱，剩下11等</li><li>9等被符合條件之武器擊殺而死，此時會掉落頭顱，剩下8等</li><li>2等被符合條件之武器擊殺而死，什麼都不會掉</li></ul></li><li>掉落玩家頭顱設定只適用於主伺服/設施服，<b>資源服不掉落</b>玩家頭顱 <img src="https://i.imgur.com/u6OyFLM.png" style="width:40%;"></li></ul></li></ul><h3 id="資源服-生物頭顱" tabindex="-1">資源服 生物頭顱 <a class="header-anchor" href="#資源服-生物頭顱" aria-label="Permalink to &quot;資源服 生物頭顱&quot;">​</a></h3><ul><li>玩家在<b>資源服</b>擊殺生物有一定機率掉落生物頭顱 <ul><li>詳細掉落機率請見<a href="https://gist.github.com/MiunaPA/2c39439c94f263a1c22829800140e24e" target="_blank" rel="noreferrer">連結</a>(伺服GitHub，英文)</li></ul></li></ul>',12)])])}const f=i(o,[["render",r]]);export{b as __pageData,f as default};
